// Uma busca para cada combinação de cidade x tipo
const f = $input.first().json;
const cidades = String(f.Cidades || '').split('\n').map(s => s.trim()).filter(Boolean);
let tipos = f.Tipos;
if (!Array.isArray(tipos)) tipos = String(tipos || 'pousada').split(',').map(s => s.trim());
const out = [];
for (const c of cidades) for (const t of tipos) out.push({ json: { textQuery: `${t} em ${c}` } });
return out;

// Limpa, remove duplicados, descarta o que não é hospedagem e dá uma nota de prioridade
const cfg = $('Config').first().json;
const HOSPEDAGEM = ['lodging','hotel','inn','motel','hostel','bed_and_breakfast','guest_house','resort_hotel','farmstay','cottage','campground','extended_stay_hotel','budget_japanese_inn','private_guest_room'];
const seen = new Set();
const out = [];
const agora = new Date().toISOString();

for (const item of $input.all()) {
  const p = item.json;
  if (!p.id || seen.has(p.id)) continue;
  seen.add(p.id);
  if (p.businessStatus && p.businessStatus !== 'OPERATIONAL') continue;
  if (!(p.types || []).some(t => HOSPEDAGEM.includes(t))) continue;

  const nome = p.displayName?.text || '';
  const endereco = p.formattedAddress || '';
  const m = endereco.match(/^(.*)\s-\s([A-Z]{2})\s*,/);
  const cidade = m ? m[1].split(/,|\s-\s/).pop().trim() : '';
  const uf = m ? m[2] : '';
  const telefone = p.nationalPhoneNumber || '';
  const dig = telefone.replace(/\D/g, '');
  const celular = dig.length === 11 && dig[2] === '9';
  const site = p.websiteUri || '';
  const nota = p.rating ?? '';
  const avaliacoes = p.userRatingCount ?? 0;
  const siteEhOta = /booking\.com|airbnb|expedia|decolar|trivago|hoteis\.com|instagram\.com|facebook\.com|wa\.me/i.test(site);

  // Prioridade: quanto maior, mais provável que tenha as dores que você resolve
  let score = 0;
  const motivos = [];
  if (!site || siteEhOta) { score += 3; motivos.push(site ? 'site é OTA/rede social' : 'sem site'); }
  if (celular) { score += 2; motivos.push('celular (provável WhatsApp)'); }
  if (avaliacoes >= 20 && avaliacoes <= 400) { score += 2; motivos.push('porte pequeno/médio'); }
  if (avaliacoes > 1500) { score -= 2; motivos.push('muito grande (provável rede)'); }
  if (nota !== '' && nota < 4.3) { score += 1; motivos.push('nota abaixo de 4,3'); }
  if (!telefone) { score -= 2; motivos.push('sem telefone'); }

  const params = new URLSearchParams({ lead: p.id, hotel: nome, cidade: cidade && uf ? `${cidade}/${uf}` : cidade, origem: 'Captação n8n', contato: telefone });

  out.push({ json: {
    place_id: p.id,
    nome, cidade, uf, endereco, telefone,
    whatsapp: celular ? `https://wa.me/55${dig}` : '',
    site, nota, avaliacoes,
    maps: p.googleMapsUri || '',
    score, motivos: motivos.join('; '),
    link_entrevista: `${cfg.questionario_url}?${params.toString()}`,
    status: 'Novo',
    temperatura: '', proximo_passo: '', data_retorno: '',
    capturado_em: agora
  }});
}
return out;
